const verified = await deps.paypal.verifyWebhook(headers, event);
if (!verified.ok || verified.body?.verification_status !== 'SUCCESS') {
  deps.db.recordDelivery({
    deliveryId,
    eventId: event.id,
    eventType: event.event_type,
    applied: 0,
  });
  return { status: 400, body: { error: 'invalid signature' } };
}
if (deps.db.hasLedgerEvent(event.id)) {
  deps.db.recordDelivery({
    deliveryId,
    eventId: event.id,
    eventType: event.event_type,
    applied: 0,
  });
  return { status: 200, body: { received: true } };
}
